def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find hollow rectangles: border color C, interior background color B
    for i in range(h):
        for j in range(w):
            # Skip if border cell
            if i == 0 or i == h-1 or j == 0 or j == w-1:
                continue

            val = result[i][j]

            # Check if this could be interior of a hollow rect
            # Interior = all 4 directions are uniform border color
            top = result[i-1][j]
            bottom = result[i+1][j]
            left = result[i][j-1]
            right = result[i][j+1]

            if top != bottom or top != left or top != right:
                # Not a coherent border, skip
                continue

            border_color = top
            if val == border_color:
