            # If any cell in this cell's horizontal vicinity has same border but extends further
            for check_left in range(j, max(0, j-20), -1):
                for check_right in range(j+1, min(w, j+20)):
                    # Check if row i-1 and i+1 have uniform border_color from check_left to check_right
                    row_top_ok = all(result[i-1][c] == border_color 
                                     for c in range(check_left, check_right+1))
                    row_bottom_ok = all(result[i+1][c] == border_color 
                                       for c in range(check_left, check_right+1))
                    row_current_left = all(result[i][c] == border_color 
                                           for c in range(check_left, j))
                    row_current_right = all(result[i][c] == border_color 
