                    if row_top_ok and row_bottom_ok and row_current_left and row_current_right:
                        # Check rows i-2, i, i+2 to see if they're already part of larger rect
                        valid = True
                        for row_offset in [-2, 2]:
                            r = i + row_offset
                            if 0 <= r < h:
                                # Check border cells
                                if check_left == j:
                                    continue  # No left cells
                                if check_right == j:
                                    continue  # No right cells
                                if r - (i-1) <= 1 or (i+1) - r <= 1:
